using FirepowerLoop.Arcade;
// 必须显式声明真实过滤和数量；不存在全套回退。
var options=args.Select(a=>a.Split('=',2)).ToDictionary(a=>a[0],a=>a.Length==2?a[1]:"");
if(!new[]{"SlayerMartRules","SlayerMartConfig","SlayerMartSave"}.Contains(options.GetValueOrDefault("testClass"))||options.GetValueOrDefault("includePassingTests")!="true"||
    !int.TryParse(options.GetValueOrDefault("maxTests"),out int max)||max<1)throw new ArgumentException("Require testClass=SlayerMartRules maxTests=N includePassingTests=true");
if(options["testClass"]=="SlayerMartConfig"){Environment.ExitCode=ConfigChecks.Run(max);return;}
if(options["testClass"]=="SlayerMartSave"){Environment.ExitCode=SaveChecks.Run(max);return;}
var prices=new long[]{3000,1500,1250,750,500,2000,2500,4000,7000,7000,7000,35000,15000,30000,2000,15000,250,250,500,2000,7000,7000,12500,7500};
var items=Enumerable.Range(1,24).Select(n=>new ArcadeSlayerMartItem("slayermart.item."+n.ToString("00"),(SlayerMartEffect)n,prices[n-1],n>=7&&n<=14||n==16||n>=21&&n<=23,n==1||n==2?2:n==3||n==18||n==19||n==20?3:1,n==4||n==5||n==6||n==20?300:0)).ToArray();
var catalog=new ArcadeSlayerMartCatalog(items,new[]{new ArcadeSlayerMartRegion(1,11,9,2000,300),new ArcadeSlayerMartRegion(2,31,11,2000,300)},16,9,9,9,5,8,16);
ArcadeSlayerMartState State(){var s=ArcadeSlayerMartRules.Create(100,1,new long[]{11,22},314,catalog);s.Ready=true;foreach(var p in s.Players){p.Lives=3;p.Cash=100000;p.Tokens=2;}return s;}
ArcadeSlayerMartRequest Req(ArcadeSlayerMartState s,SlayerMartAction action,long player=11,string item=null,int amount=0,string op="op")=>new(){Action=action,PlayerId=player,RegionInstanceId=s.RegionInstanceId,Generation=s.Generation,ExpectedRevision=s.Revision,OperationId=op,ItemId=item,ConfirmedAmount=amount};
ArcadeSlayerMartState Offer(ArcadeSlayerMartState s,int n){var p=s.Players[0];string id=items[n-1].Id;if(!p.Offers.Contains(id)){p.Offers.RemoveAt(0);p.Offers.Add(id);}return s;}
var tests=new (string,Action)[]{
 ("Sixteen distinct stable cards",()=>{var a=State();var b=State();Require(a.Players.All(p=>p.Offers.Count==16&&p.Offers.Distinct().Count()==16),"sixteen real unique offers required");Require(a.Players[0].Offers.SequenceEqual(b.Players[0].Offers),"unstable seed");}),
 ("Buy produces a candidate without mutating input",()=>{var s=Offer(State(),1);var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2),catalog);Require(r.Success&&r.Candidate.Players[0].Cash==97000&&r.Candidate.Players[0].Bombs==2,"purchase missing");Require(s.Players[0].Cash==100000&&s.Players[0].Bombs==0,"input mutated");}),
 ("Full inventory rejects without charging",()=>{var s=Offer(State(),1);s.Players[0].Bombs=9;var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2),catalog);Require(!r.Success&&r.Candidate==null&&s.Players[0].Cash==100000,"full inventory charged");}),
 ("Truncation needs explicit actual amount",()=>{var s=Offer(State(),1);s.Players[0].Bombs=8;var q=Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2);Require(!ArcadeSlayerMartRules.Evaluate(s,q,catalog).Success,"silent truncation");q.ConfirmedAmount=1;var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);Require(r.Success&&r.Candidate.Players[0].Bombs==9&&r.Candidate.Players[0].Cash==97000,"confirmed truncation");}),
 ("Cash box grants equal personal shares once",()=>{var s=State();var q=Req(s,SlayerMartAction.CollectCash);q.BoxId=1;var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);Require(r.Success&&r.Candidate.Players.All(p=>p.Cash==102000),"cash split or picker only");var q2=Req(r.Candidate,SlayerMartAction.CollectCash,22,op:"other");q2.BoxId=1;Require(!ArcadeSlayerMartRules.Evaluate(r.Candidate,q2,catalog).Success,"box twice");}),
 ("Operation replay does not repeat grants",()=>{var s=Offer(State(),1);var q=Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2);var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);var again=ArcadeSlayerMartRules.Evaluate(r.Candidate,q,catalog);Require(again.Success&&again.Replayed&&again.Candidate.Players[0].Bombs==2&&again.Candidate.PendingGrants.Count==r.Candidate.PendingGrants.Count,"duplicate grant");}),
 ("Same operation different payload is refused",()=>{var s=Offer(State(),1);var q=Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2);var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);q.ConfirmedAmount=1;Require(!ArcadeSlayerMartRules.Evaluate(r.Candidate,q,catalog).Success,"id reused");}),
 ("Reroll is personal costs one and actually changes",()=>{var s=State();var before=s.Players[1].Offers.ToArray();var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Reroll),catalog);Require(r.Success&&r.Candidate.Players[0].Tokens==1&&!s.Players[0].Offers.ToHashSet().SetEquals(r.Candidate.Players[0].Offers),"no reroll");Require(r.Candidate.Players[1].Offers.SequenceEqual(before)&&r.Candidate.Players[1].Tokens==2,"partner changed");}),
 ("No change possible never spends token",()=>{var s=State();foreach(var i in items)s.Players[0].Owned.Add(i.Id);Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Reroll),catalog).Success&&s.Players[0].Tokens==2,"useless reroll charged");}),
 ("Vest starts empty upgrade preserves plate",()=>{var s=Offer(State(),13);var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[12].Id),catalog);Require(r.Success&&r.Candidate.Players[0].VestSlots==1&&r.Candidate.Players[0].Plates==0,"free armor");s=Offer(r.Candidate,14);s.Players[0].Plates=1;r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[13].Id,op:"upgrade"),catalog);Require(r.Success&&r.Candidate.Players[0].VestSlots==2&&r.Candidate.Players[0].Plates==1,"upgrade gifted or lost plate");}),
 ("Plate requires vest and rejects full capacity",()=>{var s=Offer(State(),15);Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[14].Id),catalog).Success,"plate without vest");s.Players[0].VestSlots=1;var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[14].Id),catalog);Require(r.Success&&r.Candidate.Players[0].Plates==1,"plate unavailable");s=r.Candidate;Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[14].Id,op:"plate2"),catalog).Success,"overfilled plates");}),
 ("Per visit purchase survives rerolls",()=>{var s=Offer(State(),1);var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2),catalog);s=r.Candidate;s.Players[0].Tokens=2;var re=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Reroll,op:"reroll"),catalog);Require(re.Success,"reroll refused");s=Offer(re.Candidate,1);Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2,op:"buy2"),catalog).Success,"limit reset");}),
 ("Team extra life only charges one member",()=>{var s=Offer(State(),24);s.Players[1].Offers=s.Players[0].Offers.ToList();var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[23].Id),catalog);Require(r.Success&&r.Candidate.TeamLifeBought&&r.Candidate.PendingGrants.Count==2&&r.Candidate.Players[0].Lives==3,"life applied early");s=r.Candidate;var other=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,22,items[23].Id,op:"p2"),catalog);Require(!other.Success&&s.Players[1].Cash==100000,"team duplicate charge");}),
 ("All full lives cannot buy team benefit",()=>{var s=Offer(State(),24);foreach(var p in s.Players)p.Lives=9;Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[23].Id),catalog).Success,"no benefit charged");}),
 ("Chicken pack is atomic at five capacity",()=>{var s=Offer(State(),20);s.Players[0].Chickens=3;Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[19].Id),catalog).Success,"pack truncated");s.Players[0].Chickens=2;var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[19].Id),catalog);Require(r.Success&&r.Candidate.Players[0].Chickens==5&&r.Candidate.PendingGrants.Single().Amount==3,"not three concurrent chickens");}),
 ("Unowned personal upgrade is once per run",()=>{var s=Offer(State(),7);var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[6].Id),catalog);Require(r.Success&&r.Candidate.Players[0].Owned.Contains(items[6].Id),"mastery absent");s=r.Candidate;s.Players[0].Bought.Clear();Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[6].Id,op:"again"),catalog).Success,"unique bought twice");}),
 ("Zero life rejects personal supply but can buy team life",()=>{var s=Offer(State(),1);s.Players[0].Lives=0;Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2),catalog).Success,"dead supply");s=Offer(s,24);Require(ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[23].Id),catalog).Success,"dead member cannot help team");s.Players[1].Lives=0;Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[23].Id),catalog).Success,"all dead team revived by purchase");}),
 ("Invalid player generation or revision is rejected",()=>{var s=State();var q=Req(s,SlayerMartAction.Reroll,999);Require(!ArcadeSlayerMartRules.Evaluate(s,q,catalog).Success,"foreign player");q=Req(s,SlayerMartAction.Reroll);q.Generation++;Require(!ArcadeSlayerMartRules.Evaluate(s,q,catalog).Success,"stale map");q.Generation=s.Generation;q.ExpectedRevision++;Require(!ArcadeSlayerMartRules.Evaluate(s,q,catalog).Success,"stale revision");}),
 ("Closing rejects new operation but replays accepted one",()=>{var s=Offer(State(),1);var q=Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2);var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);s=r.Candidate;s.Closing=true;s.RemainingSeconds=0;Require(ArcadeSlayerMartRules.Evaluate(s,q,catalog).Replayed,"accepted receipt lost");Require(!ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Reroll,op:"late"),catalog).Success,"late operation");}),
 ("Cash overflow refuses whole team candidate",()=>{var s=State();s.Players[1].Cash=long.MaxValue;var q=Req(s,SlayerMartAction.CollectCash);q.BoxId=1;var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);Require(!r.Success&&r.Candidate==null&&s.Players[0].Cash==100000&&s.CollectedBoxes.Count==0,"partial overflow credit");}),
 ("Candidate deep copy isolates offers receipts grants",()=>{var s=Offer(State(),1);var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[0].Id,amount:2),catalog);var c=r.Candidate.Clone();c.Players[0].Offers.Clear();c.Receipts[0].Grants[0].Amount=90;c.PendingGrants[0].Amount=90;Require(r.Candidate.Players[0].Offers.Count==16&&r.Candidate.Receipts[0].Grants[0].Amount==2&&r.Candidate.PendingGrants[0].Amount==2,"shallow clone");}),
 ("Gem amount deterministic and request ID independent",()=>{var a=Offer(State(),17);var b=Offer(State(),17);var x=ArcadeSlayerMartRules.Evaluate(a,Req(a,SlayerMartAction.Buy,item:items[16].Id,op:"a"),catalog);var y=ArcadeSlayerMartRules.Evaluate(b,Req(b,SlayerMartAction.Buy,item:items[16].Id,op:"b"),catalog);int n=x.Candidate.PendingGrants.Single().Amount;Require(x.Success&&y.Success&&n>=8&&n<=16&&n==y.Candidate.PendingGrants.Single().Amount,"request based gems");}),
 ("Insufficient balance has no effects or receipt",()=>{var s=Offer(State(),12);s.Players[0].Cash=34999;var r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.Buy,item:items[11].Id),catalog);Require(!r.Success&&s.PendingGrants.Count==0&&s.Receipts.Count==0&&s.Players[0].Cash==34999,"partial purchase");}),
 ("Choice disagreement and open menu remain explicit",()=>{var s=State();var q=Req(s,SlayerMartAction.SelectEnter);var r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);s=r.Candidate;r=ArcadeSlayerMartRules.Evaluate(s,Req(s,SlayerMartAction.SelectSkip,22,op:"p2choice"),catalog);Require(r.Success&&r.Candidate.Players[0].Choice==1&&r.Candidate.Players[1].Choice==2,"forced team choice");s=r.Candidate;s.Players[0].Finished=true;q=Req(s,SlayerMartAction.SetMenuOpen,op:"menu");q.Value=true;r=ArcadeSlayerMartRules.Evaluate(s,q,catalog);Require(r.Success&&r.Candidate.Players[0].MenuOpen&&r.Candidate.Players[0].Finished,"menu means done");})
};
if(tests.Length>max)throw new InvalidOperationException("Test limit exceeded");int failed=0;
foreach(var(name,test)in tests)try{test();Console.WriteLine("PASS SlayerMartRules."+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL SlayerMartRules."+name+": "+ex.Message);}
Console.WriteLine($"{tests.Length-failed}/{tests.Length} passed");Environment.ExitCode=failed==0?0:1;
static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException(message);}
